# Surah Al-An'am (chapter 6) — part 15: ayat 144-154 (IDs 933-943)
SURAH = 6

ENTRIES = {
933: (
"اور اونٹ کی دو — اور گائے کی دو — کہہ دیں: کیا اس نے دونوں نر حرام کیے ہیں یا دونوں مادہ یا جو — ان — کے دونوں ماداؤں کے پیٹوں میں ہے — یا — تم — اس — پر گواہ تھے جب اللہ نے تمہیں — اس — کی — وصیت کی — پس — اس سے زیادہ ظالم کون ہے جو — لوگوں کو — بغیر علم کے — گمراہ کرنے کے لیے — اللہ پر — جھوٹ — گھڑے — بے شک اللہ — ظالموں — کو ہدایت نہیں دیتا",
"""۱۔ اونٹ اور گائے کی دو قسمیں — بھی اللہ نے حرام نہیں کیں۔
۲۔ ’’وَمِنَ الْإِبِلِ اثْنَيْنِ وَمِنَ الْبَقَرِ اثْنَيْنِ‘‘ — اور اونٹ کی دو — اور گائے کی دو — یعنی اونٹ اور گائے — نر و مادہ — دونوں حلال ہیں۔
۳۔ ’’قُلْ آلذَّكَرَيْنِ حَرَّمَ أَمِ الْأُنثَيَيْنِ أَمَّا اشْتَمَلَتْ عَلَيْهِ أَرْحَامُ الْأُنثَيَيْنِ أَمْ كُنتُمْ شُهَدَاءَ إِذْ وَصَّاكُمُ اللّٰہُ بِهَٰذَا‘‘ — کہہ دیں: کیا اس نے دونوں نر حرام کیے ہیں یا دونوں مادہ یا جو — ان — کے دونوں ماداؤں کے پیٹوں میں ہے — یا — تم — اس — پر گواہ تھے جب اللہ نے تمہیں — اس — کی — وصیت کی — یعنی یہ حرام — اللہ نے نہیں کیا — کوئی گواہ نہیں۔
۴۔ ’’فَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللّٰہِ كَذِبًا لِّيُضِلَّ النَّاسَ بِغَيْرِ عِلْمٍ إِنَّ اللّٰہَ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ‘‘ — پس — اس سے زیادہ ظالم کون ہے جو — لوگوں کو — بغیر علم کے — گمراہ کرنے کے لیے — اللہ پر — جھوٹ — گھڑے — بے شک اللہ — ظالموں — کو ہدایت نہیں دیتا — یعنی اللہ پر جھوٹ — سب سے بڑا ظلم ہے۔
۵۔ عملی سبق: اللہ پر جھوٹ مت گھڑو؛ علم کے بغیر حکم جاری مت کرو۔"""
),
934: (
"کہہ دیں: جو کچھ مجھ پر وحی کی گئی — اس — میں — میں — کوئی — حرام — چیز — نہیں پاتا جو — کوئی — کھانے والا کھاتا ہے — سوائے یہ کہ وہ مردہ ہو یا بہہتا ہوا خون یا سور کا گوشت — بے شک وہ ناپاک (رجس) ہے — یا — گناہ — وہ — جس پر اللہ کے سوا کا نام لیا گیا ہو — پس جو کوئی مجبور ہو — بغیر — سرکشی اور حد سے بڑھنے کے — تو بے شک تمہارا رب — بخشش والا — مہربان ہے",
"""۱۔ نبی ﷺ پر وحی — صرف چار حرام چیزیں — بیان۔
۲۔ ’’قُل لَّا أَجِدُ فِي مَا أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُ إِلَّا أَن يَكُونَ مَيْتَۃً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُ رِجْسٌ‘‘ — کہہ دیں: جو کچھ مجھ پر وحی کی گئی — اس — میں — میں — کوئی — حرام — چیز — نہیں پاتا جو — کوئی — کھانے والا کھاتا ہے — سوائے یہ کہ وہ مردہ ہو یا بہہتا ہوا خون یا سور کا گوشت — بے شک وہ ناپاک (رجس) ہے — یعنی اللہ نے صرف یہ استثناء مقرر فرمائے۔
۳۔ ’’أَوْ فِسْقًا أُهِلَّ لِغَيْرِ اللّٰہِ بِهِ‘‘ — یا — گناہ — وہ — جس پر اللہ کے سوا کا نام لیا گیا ہو — یعنی غیر اللہ کے نام پر ذبیحہ — حرام ہے۔
۴۔ ’’فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَّحِيمٌ‘‘ — پس جو کوئی مجبور ہو — بغیر — سرکشی اور حد سے بڑھنے کے — تو بے شک تمہارا رب — بخشش والا — مہربان ہے — یعنی اضطراری حالت میں — بقا کے لیے — اجازت ہے۔
۵۔ عملی سبق: اللہ کے حرام کردہ — اشیاء سے بچو؛ اضطرار میں — ضرورت کے مطابق اجازت — ہے۔"""
),
935: (
"اور — یہود — پر — ہم نے — ہر ناخن والا (ذی ظفر) — حرام کیا — اور گائے اور بھیڑ کے — ان — کی — چربی — بھی حرام کی — سوائے — جو — ان — کی — پیٹھ — نے اٹھایا — یا — آنتوں — یا جو ہڈی سے مل گئی ہو — یہ — ہم نے — انہیں — ان کی زیادتی کی وجہ سے بدلاہ دیا — اور بے شک ہم سچے ہیں",
"""۱۔ یہود پر — خصوصی — حرمتیں — ان — کی نافرمانی کا بدلہ۔
۲۔ ’’وَعَلَى الَّذِينَ هَادُوا حَرَّمْنَا كُلَّ ذِي ظُفُرٍ‘‘ — اور — یہود — پر — ہم نے — ہر ناخن والا (ذی ظفر) — حرام کیا — অর্থাৎ ناخن والے (پرندے وغیرہ) — یہود پر حرام تھے۔
۳۔ ’’وَمِنَ الْبَقَرِ وَالْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَا إِلَّا مَا حَمَلَتْ ظُهُورُهُمَا أَوِ الْحَوَايَا أَوْ مَا اخْتَلَطَ بِعَظْمٍ‘‘ — اور گائے اور بھیڑ کے — ان — کی — چربی — بھی حرام کی — سوائے — جو — ان — کی — پیٹھ — نے اٹھایا — یا — آنتوں — یا جو ہڈی سے مل گئی ہو — یعنی ان پر گائے و بھیڑ کی چربی حرام تھی — پیٹھ کی چربی اور ہڈی سے ملی چربی استثنا۔
۴۔ ’’ذَٰلِكَ جَزَيْنَاهُم بِبَغْيِهِمْ وَإِنَّا لَصَادِقُونَ‘‘ — یہ — ہم نے — انہیں — ان کی زیادتی کی وجہ سے بدلاہ دیا — اور بے شک ہم سچے ہیں — یعنی یہ ان کی زیادتی کا بدلہ تھا — اللہ کی بات سچی ہے۔
۵۔ عملی سبق: اللہ کے عذاب اور انعامات کے — فیصلے — میں — عدل — ہے۔"""
),
936: (
"پس اگر وہ — آپ کو — جھٹلائیں — تو کہہ دیں: تمہارا رب — بہت بڑی رحمت والا ہے — اور — اس — کی — سختی — مجرموں — سے — ٹالی — نہیں جا سکتی",
"""۱۔ جھٹلانے پر — اللہ کی رحمت اور اس کی پکڑ۔
۲۔ ’’فَإِن كَذَّبُوكَ فَقُلْ رَّبُّكُمْ ذُو رَحْمَۃٍ وَاسِعَۃٍ وَلَا يُرَدُّ بَأْسُهُ عَنِ الْقَوْمِ الْمُجْرِمِينَ‘‘ — پس اگر وہ — آپ کو — جھٹلائیں — تو کہہ دیں: تمہارا رب — بہت بڑی رحمت والا ہے — اور — اس — کی — سختی — مجرموں — سے — ٹالی — نہیں جا سکتی — یعنی اللہ کی رحمت وسیع ہے — اور مجرم — اس کی پکڑ سے نہیں بچ سکتے۔
۳۔ عملی سبق: اللہ کی رحمت پر بھروسہ رکھو؛ مجرموں کا انجام یقینی ہے۔"""
),
937: (
"عنقریب — شرک کرنے والے کہیں گے: اگر اللہ چاہتا — تو نہ ہم شرک کرتے اور نہ ہمارے باپ دادا — اور نہ ہم — کسی چیز — کو حرام کرتے — اسی طرح — ان سے پہلے والوں نے — بھی — جھٹلایا — یہاں تک کہ — وہ — ہمارا — عذاب — چکھ — گئے — کہہ دیں: کیا — تمہارے پاس — کوئی علم — ہے — تو اسے ہمارے سامنے نکالو — تم — صرف — گمان — کی پیروی کرتے ہو — اور تم — صرف اندازہ لگاتے ہو",
"""۱۔ شرک کا بہانہ — اللہ کی مشیت۔
۲۔ ’’سَيَقُولُ الَّذِينَ أَشْرَكُوا لَوْ شَاءَ اللّٰہُ مَا أَشْرَكْنَا وَلَا آبَاؤُنَا وَلَا حَرَّمْنَا مِن شَيْءٍ‘‘ — عنقریب — شرک کرنے والے کہیں گے: اگر اللہ چاہتا — تو نہ ہم شرک کرتے اور نہ ہمارے باپ دادا — اور نہ ہم — کسی چیز — کو حرام کرتے — یعنی جبر کا بہانہ۔
۳۔ ’’كَذَٰلِكَ كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا بَأْسَنَا‘‘ — اسی طرح — ان سے پہلے والوں نے — بھی — جھٹلایا — یہاں تک کہ — وہ — ہمارا — عذاب — چکھ — گئے — یعنی پچھلی امتوں نے — بھی — یہی بہانہ کیا — اور عذاب چکھا۔
۴۔ ’’قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَا إِن تَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ‘‘ — کہہ دیں: کیا — تمہارے پاس — کوئی علم — ہے — تو اسے ہمارے سامنے نکالو — تم — صرف — گمان — کی پیروی کرتے ہو — اور تم — صرف اندازہ لگاتے ہو — یعنی ان کے پاس — کوئی دلیل نہیں۔
۵۔ عملی سبق: جبر کا بہانہ — بے دلیل ہے؛ بغیر علم کے حکم مت لگاؤ۔"""
),
938: (
"کہہ دیں: پس — اللہ — کی — کامل — دلیل — ہے — پس اگر وہ چاہتا — تو — تم — سب — کو ہدایت — دے دیتا",
"""۱۔ اللہ کی دلیل — ہر چیز سے بلند۔
۲۔ ’’قُلْ فَلِلّٰہِ الْحُجَّۃُ الْبَالِغَۃُ فَلَوْ شَاءَ لَهَدَاكُمْ أَجْمَعِينَ‘‘ — کہہ دیں: پس — اللہ — کی — کامل — دلیل — ہے — پس اگر وہ چاہتا — تو — تم — سب — کو ہدایت — دے دیتا — یعنی اللہ کی دلیل آخر تک پہنچ جاتی ہے — ہدایت اللہ کی مرضی سے ہے۔
۳۔ عملی سبق: اللہ کی دلیل — حکمت — پر مبنی ہے؛ ہدایت — اللہ سے مانگو۔"""
),
939: (
"کہہ دیں: اپنے گواہ لاؤ — جو — یہ — گواہی دیں کہ اللہ نے — یہ — حرام کیا — پس اگر وہ گواہی دیں تو تم ان کے ساتھ گواہی نہ دو — اور — ان — کی خواہشات — کی — پیروی مت کرو — جنہوں نے ہماری آیات — کو جھٹلایا — اور آخرت پر ایمان نہیں رکھتے — اور — وہ — اپنے رب کے ساتھ — برابر — کرتے ہیں",
"""۱۔ بے دلیل حرام — گواہ مانگو۔
۲۔ ’’قُلْ هَلُمَّ شُهَدَاءَكُمُ الَّذِينَ يَشْهَدُونَ أَنَّ اللّٰہَ حَرَّمَ هَٰذَا‘‘ — کہہ دیں: اپنے گواہ لاؤ — جو — یہ — گواہی دیں کہ اللہ نے — یہ — حرام کیا — یعنی خود ساختہ حرام — کی دلیل مانگو۔
۳۔ ’’فَإِن شَهِدُوا فَلَا تَشْهَدْ مَعَهُمْ‘‘ — پس اگر وہ گواہی دیں تو تم ان کے ساتھ گواہی نہ دو — یعنی جھوٹے گواہوں کے ساتھ تمہاری گواہی — نہ بنے۔
۴۔ ’’وَلَا تَتَّبِعْ أَهْوَاءَ الَّذِينَ كَذَّبُوا بِآيَاتِنَا وَالَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَۃِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ‘‘ — اور — ان — کی خواہشات — کی — پیروی مت کرو — جنہوں نے ہماری آیات — کو جھٹلایا — اور آخرت پر ایمان نہیں رکھتے — اور — وہ — اپنے رب کے ساتھ — برابر — کرتے ہیں — یعنی آیات کی تکذیب اور شرک کی پیروی — مت کرو۔
۵۔ عملی سبق: بے دلیل حرام — پرستی مت کرو؛ سچے گواہ — بنو۔"""
),
940: (
"کہہ دیں: آؤ — میں — تمہیں — وہ — سناؤں جو — تمہارے — رب نے — تم پر — حرام کیا — یہ کہ تم اس کے ساتھ — کسی چیز — کو شریک نہ ٹھہراؤ — اور والدین کے ساتھ — بھلائی — (کرو) — اور اپنی اولاد کو — بھوک کی وجہ سے — قتل مت کرو — ہم تمہیں — اور — انہیں — بھی — رزق دیتے ہیں — اور — بے حیائی کے — ظاہر اور چھپی ہوئی — چیزوں — کے قریب مت جاؤ — اور — اس نفس — کو — جس کو اللہ نے حرام کیا — قتل مت کرو — مگر حق کے ساتھ — یہی — وہ ہے جس کی اس نے تمہیں وصیت کی — شاید کہ تم سمجھ جاؤ",
"""۱۔ یہ اللہ کے — اصل — حرام — ہیں۔
۲۔ ’’قُلْ تَعَالَوْا أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ أَلَّا تُشْرِكُوا بِهِ شَيْئًا‘‘ — کہہ دیں: آؤ — میں — تمہیں — وہ — سناؤں جو — تمہارے — رب نے — تم پر — حرام کیا — یہ کہ تم اس کے ساتھ — کسی چیز — کو شریک نہ ٹھہراؤ — یعنی سب سے پہلا حرام — شرک۔
۳۔ ’’وَبِالْوَالِدَيْنِ إِحْسَانًا وَلَا تَقْتُلُوا أَوْلَادَكُم مِّنْ إِمْلَاقٍ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ‘‘ — اور والدین کے ساتھ — بھلائی — (کرو) — اور اپنی اولاد کو — بھوک کی وجہ سے — قتل مت کرو — ہم تمہیں — اور — انہیں — بھی — رزق دیتے ہیں — یعنی والدین کا حق — اور اولاد کا تحفظ — دونوں۔
۴۔ ’’وَلَا تَقْرَبُوا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ‘‘ — اور — بے حیائی کے — ظاہر اور چھپی ہوئی — چیزوں — کے قریب مت جاؤ — یعنی ظاہر اور پوشیدہ — ہر — بیہودگی سے دور رہو۔
۵۔ ’’وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللّٰہُ إِلَّا بِالْحَقِّ ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَعْقِلُونَ‘‘ — اور — اس نفس — کو — جس کو اللہ نے حرام کیا — قتل مت کرو — مگر حق کے ساتھ — یہی — وہ ہے جس کی اس نے تمہیں وصیت کی — شاید کہ تم سمجھ جاؤ — یعنی ناحق قتل حرام ہے۔
۶۔ عملی سبق: اللہ کی — دس — وصیتوں — پر عمل کرو؛ شرک سے بچو؛ والدین کی عزت کرو؛ بے حیائی اور قتل سے دور رہو۔"""
),
941: (
"اور — یتیم کے مال — کے قریب — مت جاؤ — مگر — اس طریقے سے جو بہتر ہو — یہاں تک کہ وہ اپنی جوانی — کو پہنچ جائے — اور — ناپ اور ترازو — انصاف سے پورا ادا کرو — ہم — کسی نفس — کو — اس — کی طاقت سے زیادہ کا — تکلیف — نہیں دیتے — اور جب تم بولو — تو انصاف کرو — اگرچہ — وہ — قریبی رشتہ دار کیوں نہ ہو — اور اللہ کے عہد — کی پابندی کرو — یہی — وہ ہے جس کی اس نے تمہیں وصیت کی — شاید کہ تم — یاد کرو",
"""۱۔ یتیم کا مال — انصاف سے — پورا — ادا کرو۔
۲۔ ’’وَلَا تَقْرَبُوا مَالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُ‘‘ — اور — یتیم کے مال — کے قریب — مت جاؤ — مگر — اس طریقے سے جو بہتر ہو — یہاں تک کہ وہ اپنی جوانی — کو پہنچ جائے — یعنی یتیم کا مال — اس کی بہتری کے لیے تصرف کرو — دیگر — نہیں۔
۳۔ ’’وَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ بِالْقِسْطِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا‘‘ — اور — ناپ اور ترازو — انصاف سے پورا ادا کرو — ہم — کسی نفس — کو — اس — کی طاقت سے زیادہ کا — تکلیف — نہیں دیتے — یعنی انصاف سے ناپ تولو۔
۴۔ ’’وَإِذَا قُلْتُمْ فَاعْدِلُوا وَلَوْ كَانَ ذَا قُرْبَىٰ‘‘ — اور جب تم بولو — تو انصاف کرو — اگرچہ — وہ — قریبی رشتہ دار کیوں نہ ہو — یعنی انصاف — ہر حال میں — لازم ہے۔
۵۔ ’’وَبِعَهْدِ اللّٰہِ أَوْفُوا ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَذَكَّرُونَ‘‘ — اور اللہ کے عہد — کی پابندی کرو — یہی — وہ ہے جس کی اس نے تمہیں وصیت کی — شاید کہ تم — یاد کرو — یعنی اللہ کا عہد پورا کرو۔
۶۔ عملی سبق: یتیم کا مال — صحیح مصرف — کرو؛ ناپ تول میں انصاف کرو؛ حق بولو؛ اللہ کے عہد کی پابندی کرو۔"""
),
942: (
"اور — یہ — میری سیدھی راہ ہے — پس — اس — کی پیروی کرو — اور راستوں کی پیروی مت کرو — وہ — تمہیں — اس — کے — راستے سے — الگ کر دیں گے — یہی — وہ ہے جس کی اس نے تمہیں وصیت کی — شاید کہ تم پرہیزگار ہو جاؤ",
"""۱۔ اللہ کی — سیدھی راہ — صرف ایک ہے۔
۲۔ ’’وَأَنَّ هَٰذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِ‘‘ — اور — یہ — میری سیدھی راہ ہے — پس — اس — کی پیروی کرو — اور راستوں کی پیروی مت کرو — وہ — تمہیں — اس — کے — راستے سے — الگ کر دیں گے — یعنی آپسی اختلافات — گمراہی — ہیں۔
۳۔ ’’ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَتَّقُونَ‘‘ — یہی — وہ ہے جس کی اس نے تمہیں وصیت کی — شاید کہ تم پرہیزگار ہو جاؤ — یعنی سیدھے راستے پر چلو — تقویٰ حاصل کرو۔
۴۔ عملی سبق: اللہ کے سیدھے راستے کی پیروی کرو؛ گروہوں میں تقسیم سے بچو۔"""
),
943: (
"پھر ہم نے — موسیٰؑ — کو — کتاب عطا کی — پوری — نیکی کرنے والوں پر — اور ہر چیز کی — تفصیل — اور ہدایت اور رحمت — شاید کہ وہ — اپنے — رب — سے — ملاقات — پر ایمان لائیں",
"""۱۔ موسیٰؑ کو — کتاب — دی گئی۔
۲۔ ’’ثُمَّ آتَيْنَا مُوسَى الْكِتَابَ تَمَامًا عَلَى الَّذِي أَحْسَنَ وَتَفْصِيلًا لِّكُلِّ شَيْءٍ وَهُدًى وَرَحْمَۃً‘‘ — پھر ہم نے — موسیٰؑ — کو — کتاب عطا کی — پوری — نیکی کرنے والوں پر — اور ہر چیز کی — تفصیل — اور ہدایت اور رحمت — یعنی تورات — مکمل کتاب — ہر چیز کی تفصیل رکھتی ہے۔
۳۔ ’’لَّعَلَّهُم بِلِقَاءِ رَبِّهِمْ يُؤْمِنُونَ‘‘ — شاید کہ وہ — اپنے — رب — سے — ملاقات — پر ایمان لائیں — یعنی تورات — ملاقاتِ الٰہی — پر ایمان لانے — کے لیے تھی۔
۴۔ عملی سبق: اللہ کی کتاب — پر ایمان رکھو؛ آخرت کی تیاری کرو۔"""
),
}
